function validate([n, relations, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 15) return 'n is an integer between 1 and 15.';
  if (!Number.isInteger(k) || k < 1 || k > n) return 'k is between 1 and n.';
  if (!Array.isArray(relations) || relations.length > n * (n - 1) / 2) return 'relations has at most n * (n - 1) / 2 pairs.';
  const seen = new Set();
  const indegree = new Array(n + 1).fill(0);
  const next = Array.from({ length: n + 1 }, () => []);
  for (const pair of relations) {
    if (!Array.isArray(pair) || pair.length !== 2) return 'Each relation is a pair [prevCourse, nextCourse].';
    const [a, b] = pair;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 1 || a > n || b < 1 || b > n) return 'Courses are numbered 1 to n.';
    if (a === b) return 'A course cannot be its own prerequisite.';
    if (seen.has(a * 16 + b)) return 'Each relation may appear only once.';
    seen.add(a * 16 + b);
    next[a].push(b);
    indegree[b]++;
  }
  const queue = [];
  for (let c = 1; c <= n; c++) if (indegree[c] === 0) queue.push(c);
  for (let q = 0; q < queue.length; q++) {
    for (const b of next[queue[q]]) if (--indegree[b] === 0) queue.push(b);
  }
  if (queue.length !== n) return 'The prerequisites must not form a cycle.';
  return null;
}

