function minNumberOfSemesters(n, relations, k) {
  const prereq = new Array(n).fill(0);
  for (const [before, after] of relations) {
    prereq[after - 1] |= 1 << (before - 1);
  }

  const full = (1 << n) - 1;
  const bits = new Array(full + 1).fill(0);
  for (let mask = 1; mask <= full; mask++) {
    bits[mask] = bits[mask >> 1] + (mask & 1);
  }

  const dp = new Array(full + 1).fill(Infinity);
  dp[0] = 0;
  for (let mask = 0; mask < full; mask++) {
    if (dp[mask] === Infinity) continue;
    let ready = 0;
    for (let course = 0; course < n; course++) {
      const taken = (mask >> course) & 1;
      if (!taken && (prereq[course] & mask) === prereq[course]) {
        ready |= 1 << course;
      }
    }
    if (bits[ready] <= k) {
      dp[mask | ready] = Math.min(dp[mask | ready], dp[mask] + 1);
      continue;
    }
    for (let pick = ready; pick > 0; pick = (pick - 1) & ready) {
      if (bits[pick] === k) {
        dp[mask | pick] = Math.min(dp[mask | pick], dp[mask] + 1);
      }
    }
  }
  return dp[full];
}

