function minNumberOfSemesters(n, relations, k) {
  // Breadth-first search over sets of finished courses, trying every non-empty batch of at most k ready courses.
  const need = Array.from({ length: n }, () => []);
  for (const [a, b] of relations) need[b - 1].push(a - 1);
  const goal = (1 << n) - 1;
  const dist = new Map([[0, 0]]);
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    const done = queue[q];
    const ready = [];
    for (let c = 0; c < n; c++) {
      if (!((done >> c) & 1) && need[c].every(p => (done >> p) & 1)) ready.push(c);
    }
    // Every batch of 1..k ready courses, built as combinations of the ready list.
    let found = false;
    const extend = (from, count, next) => {
      if (found) return;
      if (count > 0 && !dist.has(next)) {
        dist.set(next, dist.get(done) + 1);
        if (next === goal) { found = true; return; }
        queue.push(next);
      }
      if (count === k) return;
      for (let i = from; i < ready.length; i++) extend(i + 1, count + 1, next | (1 << ready[i]));
    };
    extend(0, 0, done);
    if (found) return dist.get(goal);
  }
  return -1;
}

