function generate(rand, size) {
  // Up to 13 courses keeps the O(3^n) worst case well inside the local time limit.
  const n = size === 'large' ? 11 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 8);
  const density = size === 'large' ? rand() * 0.3 : rand() * 0.6;
  // A random order of the courses; edges only go forward in it, so the graph has no cycle.
  const order = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
  }
  const relations = [];
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      if (rand() < density) relations.push([order[i], order[j]]);
    }
  }
  for (let i = relations.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [relations[i], relations[j]] = [relations[j], relations[i]];
  }
  const k = 1 + Math.floor(rand() * n);
  return [n, relations, k];
}
